#[actix_web::test]
async fn find_returns_entity_as_json() {
    let state = AppState::with_items(&[(7, "seven")]);
    let app = init!(state);

    let req = test::TestRequest::get().uri("/v1/item/7").to_request();
    let resp = test::call_service(&app, req).await;

    assert_eq!(resp.status(), StatusCode::OK);
    let body: Item = test::read_body_json(resp).await;
    assert_eq!(
        body,
        Item {
            id: 7,
            content: "seven".into(),
            deleted: false
        }
    );
}

#[actix_web::test]
async fn find_forwards_query_string_to_model() {
    let state = AppState::with_items(&[(7, "seven")]);
    let app = init!(state);

    let req = test::TestRequest::get()
        .uri("/v1/item/7?expand=owner")
        .to_request();
    let resp = test::call_service(&app, req).await;

    assert_eq!(resp.status(), StatusCode::OK);
    assert_eq!(
        *state.last_find_query.lock().unwrap(),
        Some(FindQuery {
            expand: Some("owner".into())
        })
    );
}

