// ---------------------------------------------------------------------------
// PUT /v1/item/{id}
// ---------------------------------------------------------------------------

#[actix_web::test]
async fn update_existing_entity_returns_updated_entity() {
    let state = AppState::with_items(&[(3, "old")]);
    let app = init!(state);

    let req = test::TestRequest::put()
        .uri("/v1/item/3")
        .set_json(serde_json::json!({ "id": 3, "content": "updated" }))
        .to_request();
    let resp = test::call_service(&app, req).await;

    assert_eq!(resp.status(), StatusCode::OK);
    let body: UpdatableItem = test::read_body_json(resp).await;
    assert_eq!(
        body,
        UpdatableItem {
            id: 3,
            content: "updated".into()
        }
    );
    assert_eq!(state.items.lock().unwrap()[&3].content, "updated");
}

#[actix_web::test]
async fn update_unknown_id_returns_404_without_calling_update() {
    let state = AppState::with_items(&[]);
    let app = init!(state);

    let req = test::TestRequest::put()
        .uri("/v1/item/3")
        .set_json(serde_json::json!({ "id": 3, "content": "updated" }))
        .to_request();
    let resp = test::call_service(&app, req).await;

    assert_eq!(resp.status(), StatusCode::NOT_FOUND);
    assert_eq!(body_string(resp).await, "ENTITY_NOT_FOUND");
    assert_eq!(state.update_calls.load(Ordering::SeqCst), 0);
}

#[actix_web::test]
async fn update_with_payload_id_different_from_path_id_returns_400() {
    let state = AppState::with_items(&[(3, "three"), (5, "five")]);
    let app = init!(state);

    let req = test::TestRequest::put()
        .uri("/v1/item/3")
        .set_json(serde_json::json!({ "id": 5, "content": "updated" }))
        .to_request();
    let resp = test::call_service(&app, req).await;

    assert_eq!(resp.status(), StatusCode::BAD_REQUEST);
    assert_eq!(body_string(resp).await, "ID_MISMATCH");
    assert_eq!(state.update_calls.load(Ordering::SeqCst), 0);
    let items = state.items.lock().unwrap();
    assert_eq!(items[&3].content, "three");
    assert_eq!(items[&5].content, "five");
}

