// ---------------------------------------------------------------------------
// Routing
// ---------------------------------------------------------------------------

#[actix_web::test]
async fn routes_outside_scope_are_not_registered() {
    let state = AppState::with_items(&[(1, "a")]);
    let app = init!(state);

    for uri in ["/item/1", "/v1/items/1", "/v2/item/1"] {
        let req = test::TestRequest::get().uri(uri).to_request();
        let resp = test::call_service(&app, req).await;
        assert_eq!(resp.status(), StatusCode::NOT_FOUND, "GET {}", uri);
    }
}

#[actix_web::test]
async fn unsupported_methods_are_not_routed_to_handlers() {
    let state = AppState::with_items(&[(1, "a")]);
    let app = init!(state);

    let patch = test::TestRequest::patch().uri("/v1/item/1").to_request();
    assert!(test::call_service(&app, patch).await.status().is_client_error());

    let post_on_id = test::TestRequest::post()
        .uri("/v1/item/1")
        .set_json(serde_json::json!({ "content": "x" }))
        .to_request();
    assert!(test::call_service(&app, post_on_id)
        .await
        .status()
        .is_client_error());

    assert_eq!(state.items.lock().unwrap().len(), 1);
}
